{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Selegiline absolute oral bioavailability was 4% in healthy volunteers after a single 10-mg oral dose compared with an IV reference.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Brexanolone oral bioavailability was <5% in humans, requiring intravenous administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Amitriptyline absolute oral bioavailability was 48±11% in humans, supporting F ≥ 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Higher-transfer evidence consistently shows low absolute oral bioavailability (selegiline 4%, brexanolone <5%), while higher-F evidence such as amitriptyline 48% comes from lower-transfer records; therefore low is better supported.",
  "evidence_gaps": [
    "Molecule 1's 5–40% range straddles the 20% threshold and is uninformative.",
    "Alfentanil has conflicting ordinary-condition values (37% vs a table value of 1%) and rifampin-altered low values.",
    "Selegiline includes a melt-in-mouth formulation with 45% F, but ordinary oral tablets consistently show 4–10%; formulation difference adds uncertainty.",
    "Amiodarone has one qualitative 'low' report conflicting with numeric 35–65% values."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

